974	# truncate it before the read finishes. The rewrite keeps the same inode, and the live writers append
975	# with O_APPEND (lsof +fg shows AP for everythingd and this job's stdout), so their next line lands at
976	# the new end. shortcut: a line appended between the read and the rewrite is lost; fine for logs.
977	function Invoke-LogTrim([string[]]$paths) {
978	    foreach ($f in $paths) {
