715	    if ($missing.Count -gt 0) { Log "MANIFEST $($missing.Count) declared dir(s) absent from disk: $($missing -join ', ')" }
716	
717	    foreach ($entry in ($Manifest.paths | Where-Object { $_.path -like 'DEV/*' })) {
718	        $name = $entry.path -replace '^DEV/', ''
719	        $src = "$DevRoot/$name"
720	        if (-not (Test-Path $src)) { continue }
721	
722	        if (-not $entry.isRepo) {
723	            if ($SsdOnline) {
724	                $ok = Snapshot-Additive $src (Join-Path $SsdRoot "DEV-nonrepo/$name") @('.playwright-mcp')
725	                if (-not $ok) { $Errors.Add("snapshot-ssd:$name") }
726	            }
727	            if ($entry.destinations -contains 'baylor' -and $B -and (Test-Path (Split-Path $B -Parent))) {
728	                Snapshot $src "$B/$name" @('.playwright-mcp')
729	            }
730	        }
731	        elseif ($SsdOnline -and ($entry.captureOrphans -or $entry.captureWorkingTree)) {
732	            $n = Capture-RepoData $src $name $SsdRoot
733	            if ($n -gt 0) { Log "CAPTURE $name : $n file(s) git does not carry" }
734	            $Results.Add(@{ kind = 'capture'; name = $name; status = 'OK' })
735	        }
736	    }
737	
738	    # Non-DEV manifest paths (~/.claude subtrees, .codex, .gemini, SecondBrain) -> SSD.
739	    if ($SsdOnline) {
740	        foreach ($entry in ($Manifest.paths | Where-Object { $_.path -notlike 'DEV/*' -and $_.destinations -contains 'ssd' })) {
741	            $rel = $entry.path
742	            $src = Join-Path $U $rel
743	            if (-not (Test-Path $src)) { continue }
744	            $leaf = Split-Path $rel -Leaf
745	            $sub = switch -Wildcard ($entry.path) {
746	                '.claude/*'  { "claude/$leaf" }
747	                'Desktop/*'  { $leaf }
748	                default      { $leaf -replace '^\.', '' }
749	            }
750	            $extra = @()
751	            # R23 (2026-10-24): also skip Codex's app-owned, regenerable trees. A leading '/' anchors the
752	            # rsync exclude to the top of ~/.codex ('/cache' -> --exclude=/cache/), so a nested folder of the
753	            # same name is still copied. The manifest has no excludes field, so this list lives here.
754	            if ($entry.path -eq '.codex') { $extra = @('work', '/packages', '/plugins', '/.tmp', '/cache', '/computer-use', '/visualizations') }
755	            if ($entry.path -eq '.gemini') { $extra = @('antigravity_browser_profile') }
756	            if ($entry.path -eq 'SecondBrain') { $extra = @('.git') }   # vault moved off Desktop 2026-08-14; github dest covers tracked files
757	            $ok = Snapshot-Additive $src (Join-Path $SsdRoot $sub) $extra
758	            if ($ok) { Log "STATE-SSD $($entry.path) -> $sub : OK" }
759	            else { $Errors.Add("snapshot-ssd:$($entry.path)"); Log "STATE-SSD $($entry.path) : FAILED" }
760	        }
761	    }
762	
763	    # Receipts: prove each destination accepted a write in THIS run.
764	    if ($SsdRoot -and (Test-Path $SsdRoot)) {
765	        if ($DryRun) { Log "RECEIPT ssd : skipped (dry run wrote nothing to verify)" }
766	        elseif (Write-Receipt $SsdRoot $RunId) { Log "RECEIPT ssd : verified run=$RunId" }
767	        else { $Errors.Add("receipt-failed:ssd"); Log "RECEIPT ssd : FAILED - destination did not read back the sentinel" }
768	    }
769	    if ($DryRun) { Log "RECEIPT drive : skipped (dry run wrote nothing to verify)" }

